function sx(x){return x-game.camera}
function spriteRowForPlayer(){if(game.player.flash>0||game.player.action==='hurt')return 4;if(game.player.action==='plasma')return 3;if(game.player.action==='attack')return 2;if(Math.abs(game.player.vx)>5)return 1;return 0}
