function drawProjectiles(){for(const b of game.enemyProjectiles||[]){const x=sx(b.x),y=laneY(b.lane,room().lanes||1)+30;ctx.strokeStyle='#ffd6a0';ctx.globalAlpha=.8;ctx.beginPath();ctx.moveTo(x-8,y);ctx.lineTo(x+8,y);ctx.stroke();ctx.globalAlpha=1}for(const b of game.projectiles){const x=sx(b.x),y=laneY(b.lane,room().lanes||1)+32;if(b.kind==='shuriken'){ctx.save();ctx.translate(x,y);ctx.rotate(b.spin||0);ctx.strokeStyle='#d5dcd7';ctx.lineWidth=3;for(let i=0;i<4;i++){ctx.rotate(Math.PI/2);ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(12,0);ctx.stroke()}ctx.restore()}else{const g=ctx.createRadialGradient(x,y,0,x,y,16);g.addColorStop(0,'#eaffdc');g.addColorStop(.35,'#83f1b4');g.addColorStop(1,'#2c8f7000');ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y,16,0,Math.PI*2);ctx.fill()}}for(const m of game.mines){const x=sx(m.x),y=laneY(m.lane,room().lanes||1)+84;ctx.strokeStyle=m.armed>0?'#6d554f':'#e26b55';ctx.globalAlpha=m.armed>0?.35:.8;ctx.beginPath();ctx.moveTo(x-64,y);ctx.lineTo(x+64,y);ctx.stroke();ctx.globalAlpha=1;ctx.fillStyle='#7b5a50';ctx.fillRect(x-8,y-7,16,7)}for(const s of game.slashes){const x=sx(s.x),y=laneY(s.lane,room().lanes||1)+36;ctx.strokeStyle=s.kind==='whip'?'#c3aa82':'#d7dfd9';ctx.globalAlpha=clamp(s.life/.18,0,1);ctx.lineWidth=s.kind==='whip'?4:3;ctx.beginPath();if(s.kind==='whip'){ctx.arc(x,y,85,-1.6,1.2)}else{ctx.moveTo(x-35*s.facing,y-25);ctx.lineTo(x+35*s.facing,y+20)}ctx.stroke();ctx.globalAlpha=1}}
