function drawBossTelegraph(){const b=game.enemies.find(e=>e.type==='predalien'&&e.alive);if(!b?.telegraph)return;const total=D.hunterProtocol?.bossTelegraphSeconds||.62,q=1-clamp(b.telegraph/total,0,1),x=sx(b.x+b.w/2),y=laneY(b.lane,room().lanes||1)+8;ctx.save();ctx.strokeStyle=b.specialKind==='tail'?'#d8655a':'#e6b76b';ctx.lineWidth=4;ctx.globalAlpha=.72;ctx.beginPath();ctx.arc(x,y-66,54+q*24,-Math.PI/2,-Math.PI/2+Math.PI*2*q);ctx.stroke();ctx.fillStyle=b.specialKind==='tail'?'#f19a8e':'#f3d39b';ctx.font='700 11px monospace';ctx.textAlign='center';ctx.fillText(b.specialKind==='tail'?'DARD CAUDAL':'CHARGE',x,y-132);ctx.restore()}
function drawBossBar(){const b=game.enemies.find(e=>e.type==='predalien'&&e.alive)||game.grapple?.boss;if(!b)return;const label=game.grapple?.active?'PREDALIEN // LUTTE FINALE':game.state.flags.duelGearShed?'PREDALIEN // CORPS-À-CORPS':game.state.flags.gauntletDamaged?'PREDALIEN // GAUNTLET HS':'PREDALIEN // DUEL FINAL';ctx.fillStyle='#03100ddb';ctx.fillRect(360,22,560,30);ctx.fillStyle='#8a674d';ctx.fillRect(364,27,552*(b.hp/b.maxHp),17);ctx.strokeStyle='#b28a65';ctx.strokeRect(364,27,552,17);ctx.fillStyle='#eee4d9';ctx.font='12px monospace';ctx.textAlign='center';ctx.fillText(label,640,18);ctx.textAlign='left'}
function drawVision(){if(game.state.vision===1){ctx.fillStyle='#d46a1f24';ctx.fillRect(0,0,W,H);ctx.globalCompositeOperation='screen';for(const e of game.enemies){if(!e.alive)continue;const x=sx(e.x+e.w/2),y=laneY(e.lane,room().lanes||1);const g=ctx.createRadialGradient(x,y,0,x,y,80);g.addColorStop(0,'#ffcf66aa');g.addColorStop(1,'#ff4e0000');ctx.fillStyle=g;ctx.fillRect(x-90,y-90,180,180)}ctx.globalCompositeOperation='source-over'}if(game.state.vision===2){ctx.fillStyle='#173b2a2b';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#81ffa0';ctx.lineWidth=2;for(const e of game.enemies){if(e.alive){const x=sx(e.x),y=laneY(e.lane,room().lanes||1)+(94-e.h);ctx.strokeRect(x-6,y-6,e.w+12,e.h+12)}}}}
function drawCinematic(){if(!game.cinematic?.time)return;const t=game.cinematic.time,alpha=clamp(Math.min(2.35-t,t)/.35,0,1);ctx.save();ctx.globalAlpha=alpha;ctx.fillStyle='#000';ctx.fillRect(0,0,W,58);ctx.fillRect(0,H-58,W,58);ctx.fillStyle='#d7e6d9';ctx.textAlign='center';ctx.font='600 22px monospace';ctx.fillText(game.cinematic.title,W/2,H/2-12);ctx.fillStyle='#8da398';ctx.font='12px monospace';ctx.fillText(game.cinematic.subtitle,W/2,H/2+16);ctx.textAlign='left';ctx.restore()}
function drawChapterDebrief(){const d=game.chapterDebrief;if(!d?.time)return;const a=clamp(d.time/1.2,0,1);ctx.save();ctx.globalAlpha=Math.min(.92,a);ctx.fillStyle='#06100eea';ctx.fillRect(W-330,H-160,310,126);ctx.strokeStyle='#6c8a74';ctx.strokeRect(W-330,H-160,310,126);ctx.fillStyle='#b7e37a';ctx.font='700 13px monospace';ctx.fillText(`CHASSE // CH.${String(d.chapter).padStart(2,'0')} NETTOYÉ`,W-312,H-132);ctx.fillStyle='#dce9e1';ctx.font='12px monospace';ctx.fillText(`RANG ${d.rank} · HONNEUR ${Math.round(d.score||0)}`,W-312,H-106);ctx.fillStyle='#8da398';ctx.font='11px monospace';ctx.fillText(`TRACES ${d.cleanups||0} · SANS DÉGÂT ${d.perfect||0}`,W-312,H-82);ctx.fillText(`CHAÎNE MAX ${game.state.hunt.bestChain||0}`,W-312,H-60);ctx.restore()}
function draw(){if(!game)return;const r=room(),shakeOn=game.state.options?.shake!==false,j=shakeOn&&game.shake>0?(Math.random()-.5)*game.shake:0,k=shakeOn&&game.shake>0?(Math.random()-.5)*game.shake:0;ctx.save();ctx.translate(j,k);drawBackground(r,game.state.time);drawHazards();drawTracking();drawEvidence();drawTarget();drawProjectiles();const sorted=[...game.enemies].sort((a,b)=>a.lane-b.lane);for(const e of sorted)drawEnemy(e);drawWolf();drawParticles();drawVision();drawBossTelegraph();drawBossBar();ctx.fillStyle='#6b8a7e';ctx.font='10px monospace';ctx.fillText(`${Math.round(game.camera)}m / ${WORLD-W}`,14,H-12);ctx.restore();if(game.flash>0&&game.state.options?.flash!==false){ctx.fillStyle='#ffffff22';ctx.fillRect(0,0,W,H)}drawCinematic();drawChapterDebrief()}

function renderWeapons(){ui.weaponStrip.innerHTML='';D.weapons.forEach((w,i)=>{const d=document.createElement('div');d.className='weapon-slot '+(game?.state.weapon===w.id?'active ':'')+(game&&!weaponAvailable(w)?'locked':'');d.textContent=i+1;d.title=w.name;ui.weaponStrip.appendChild(d)})}
function updateUI(){if(!game)return;const r=room(),c=D.chapters[r.c],w=currentWeapon(),sync=Math.round(100*game.state.syncBeats/Math.max(1,game.state.totalBeats)),alive=game.enemies.filter(e=>e.alive),threat=game.grapple?.active?'GRAPPLE':alive.some(e=>e.type.startsWith('predalien'))?'PREDALIEN':alive.length?String(alive.length)+' CONTACT'+(alive.length>1?'S':''):game.state.cloak?'FURTIF':'CALME';ui.healthText.textContent=Math.round(game.health);ui.energyText.textContent=Math.round(game.state.energy);ui.syncText.textContent=sync+'%';ui.cleanupText.textContent=game.state.completedEvidence+'/'+game.state.totalEvidence;ui.timeText.textContent=formatTime(game.state.time);if(ui.threatText)ui.threatText.textContent=threat;if(ui.scoreText)ui.scoreText.textContent=Math.round(game.state.hunt.score||0);if(ui.rankText)ui.rankText.textContent=huntRank();if(ui.chainText)ui.chainText.textContent=(game.state.hunt.chain||0)+'×';if(ui.stanceText)ui.stanceText.textContent=game.grapple?.active?'F/E':game.player.parry>0?'PARADE':game.player.dodgeTimer>0?'ESQUIVE':game.state.cloak?'CLOAK':'CHASSE';ui.healthBar.style.width=game.health+'%';ui.energyBar.style.width=game.state.energy+'%';ui.syncBar.style.width=sync+'%';ui.chapterText.textContent=`CH.${String(r.c).padStart(2,'0')} — ${c.title}`;ui.objectiveText.textContent=r.objective;ui.roomText.innerHTML=`${r.name}<span class="badge ${r.fidelity}">${r.fidelity.toUpperCase()}</span> · ${difficultyProfile().label} · PLAN ${game.player.lane+1}/${r.lanes||1}`;ui.weaponText.textContent=w.name;const ammo=w.id==='shuriken'?game.state.inventory.shuriken:w.id==='mine'?game.state.inventory.mines:'∞';ui.ammoText.textContent=`MUN ${ammo} · GEL ${game.state.inventory.fluid} · MED ${game.state.inventory.med}`;ui.visionText.textContent=['VISION NORMALE','THERMIQUE','XÉNOMORPHE'][game.state.vision]+(game.state.cloak?' · CLOAK':'')+(game.state.flags.maskRemoved?' · SANS BIOMASK':'');if(ui.gearText){const g=[];g.push(game.state.flags.maskRemoved?'MASK: RETIRÉ':'MASK: ACTIF');g.push(game.state.flags.castersGone?'CASTERS: CONVERTIS':'CASTERS: DOUBLES');if(game.state.flags.pistolBuilt)g.push(game.state.flags.pistolLost?'PISTOL: PERDU':'PISTOL: ACTIF');if(game.state.flags.gauntletDamaged)g.push('GAUNTLET: HS');else g.push('GAUNTLET: ACTIF');if(game.state.flags.wounded&&!game.state.flags.healed)g.push('BLESSURE: OUVERTE');const trauma=Math.round(game.state.injury?.trauma||0);if(trauma>0)g.push('TRAUMA: '+trauma+'%');if((game.state.injury?.acid||0)>0)g.push('ACIDE: '+Math.round(game.state.injury.acid)+'%');ui.gearText.textContent=g.join(' · ')}renderWeapons()}
function renderRoute(){if(!game)return;ui.routeGrid.innerHTML='';for(const r of D.rooms){if(r.fidelity==='unrated'&&!game.state.unrated)continue;const d=document.createElement('div');d.className=`node ${r.id===game.state.room?'current ':''}${game.state.visited.includes(r.id)?'visited ':''}${r.fidelity==='unrated'?'unrated ':''}${r.fidelity==='reconstruction'?'reconstruction ':''}${game.state.hunt.perfectRoomIds?.includes(r.id)?'perfect ':''}`;d.innerHTML=`<b>${String(r.c).padStart(2,'0')} · ${r.name}</b><span>${r.fidelity}</span>`;ui.routeGrid.appendChild(d)}}
function toggleRoute(){ui.routeOverlay.classList.toggle('hidden');if(!ui.routeOverlay.classList.contains('hidden'))renderRoute()}
