function loop(ts){if(!game)return;const dt=Math.min(.034,(ts-last)/1000||0);last=ts;update(dt);draw();raf=requestAnimationFrame(loop)}
function keydown(e){if(['ArrowLeft','ArrowRight','ArrowUp','Space'].includes(e.code))e.preventDefault();if(e.repeat&&e.code!=='KeyH')return;keys.add(e.code);if(!game)return;if(e.code==='KeyE')interact();else if(e.code==='KeyF')attack();else if(e.code==='KeyQ')parry();else if(e.code==='ShiftLeft'||e.code==='ShiftRight')dodge();else if(e.code==='KeyK')toggleSound();else if(e.code==='KeyV'&&!game.state.flags.maskRemoved)game.state.vision=(game.state.vision+1)%3;else if(e.code==='KeyC'&&!game.state.flags.duelGearShed){if(game.state.energy>10)game.state.cloak=!game.state.cloak}else if(e.code==='KeyT')scan();else if(e.code==='KeyR')cleaner();else if(e.code==='KeyG')placeMine();else if(e.code==='KeyM')toggleRoute();else if(e.code==='KeyP'||e.code==='Escape')togglePause();else if(/^Digit[1-8]$/.test(e.code))chooseWeapon(Number(e.code.slice(-1))-1)}
addEventListener('keydown',keydown);addEventListener('keyup',e=>{keys.delete(e.code);if(e.code==='KeyH')endHold()});addEventListener('blur',()=>keys.clear());canvas.addEventListener('pointerdown',()=>canvas.focus());
const selectedDifficulty=()=>$('difficultySelect')?.value||'canon';$('startUnrated').onclick=()=>start(true,null,selectedDifficulty());$('startTheatrical').onclick=()=>start(false,null,selectedDifficulty());$('continueBtn').onclick=()=>{const s=load();if(s)start(s.unrated,s,s.difficulty);else toast('Aucune sauvegarde v0.7.')};$('continueBtn').disabled=!load();$('resume').onclick=togglePause;if($('retryCheckpoint'))$('retryCheckpoint').onclick=()=>{ui.pause.classList.add('hidden');game.state.paused=false;retryCheckpoint(false)};if($('shakeBtn'))$('shakeBtn').onclick=()=>{game.state.options.shake=!game.state.options.shake;$('shakeBtn').textContent='SECOUSSES: '+(game.state.options.shake?'ON':'OFF');save()};if($('flashBtn'))$('flashBtn').onclick=()=>{game.state.options.flash=!game.state.options.flash;$('flashBtn').textContent='FLASH: '+(game.state.options.flash?'ON':'OFF');save()};$('restart').onclick=()=>{localStorage.removeItem(D.saveKey);location.reload()};if($('soundBtn'))$('soundBtn').onclick=toggleSound;$('routeBtn').onclick=toggleRoute;$('saveBtn').onclick=()=>{save();toast('Sauvegarde locale écrite.')};$('resetBtn').onclick=()=>{localStorage.removeItem(D.saveKey);location.reload()};$('endRestart').onclick=()=>{localStorage.removeItem(D.saveKey);location.reload()};$('endRoute').onclick=()=>{ui.end.classList.add('hidden');toggleRoute()};
for(const b of document.querySelectorAll('[data-touch]')){const a=b.dataset.touch;const down=e=>{e.preventDefault();if(a==='left')keys.add('KeyA');if(a==='right')keys.add('KeyD');if(a==='up'){keys.add('KeyW');setTimeout(()=>keys.delete('KeyW'),100)}if(a==='down'){keys.add('KeyS');setTimeout(()=>keys.delete('KeyS'),100)}if(a==='attack')attack();if(a==='interact')interact();if(a==='parry')parry();if(a==='dodge')dodge();if(a==='vision'&&game&&!game.state.flags.maskRemoved)game.state.vision=(game.state.vision+1)%3;if(a==='scan')scan();if(a==='cloak'&&game&&!game.state.flags.duelGearShed&&game.state.energy>10)game.state.cloak=!game.state.cloak;if(a==='clean')cleaner();if(a==='mine')placeMine();if(a==='med')keys.add('KeyH')};const up=()=>{if(a==='left')keys.delete('KeyA');if(a==='right')keys.delete('KeyD');if(a==='med'){keys.delete('KeyH');endHold()}};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up)}
